// MigratorV1V2 has zero V1 contract references — only the snapshot arrays.
// constructor only takes (usdc, phUSD, phlimboV2). No V1 address.
constructor(address _usdc, address _phUSD, address _phlimboV2) Ownable(msg.sender) {
    require(_usdc != address(0), "Invalid USDC address");
    require(_phUSD != address(0), "Invalid phUSD address");
    require(_phlimboV2 != address(0), "Invalid phlimboV2 address");
    usdc = IERC20(_usdc);
    phUSD = IFlax(_phUSD);
    phlimboV2 = IPhlimboV2(_phlimboV2);
}

// migrateDeposits uses owner-supplied phUSD, never V1's:
phUSD.forceApprove(address(phlimboV2), type(uint256).max);
for (; i < end; i++) {
    uint256 dep = deposits[i];
    if (dep > 0) {
        phlimboV2.stake(dep, users[i]);   // <-- creates a new V2 position for users[i] using migrator's pre-funded phUSD
        totalPHUSD_deposited -= dep;
    }
}

// V1's withdraw remains callable while migration runs:
// V1.withdraw: external whenNotPaused — works while V1 is unpaused.
// V1.pauseWithdraw: external whenPaused — works while V1 IS paused.
